#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;
using VfxKit;
using static VfxKit.VfxBuildKit;

namespace VfxEffects
{
    // Generated by unity-vfx-maker. The prefab is rebuilt from this script: edit here, not in the Inspector.
    // Plan: Docs/VFX/Explosion/Plan.md   Shapes: Docs/VFX/Explosion/Shapes/ (Shape Lab)
    public static class ExplosionBuild
    {
        const string Effect = "Explosion";
        const string Root = "Assets/VFX/" + Effect;
        const float TwoPi = Mathf.PI * 2f;

        [MenuItem("VFX/" + Effect + "/Build")]
        public static void Build()
        {
            if (!ConfirmSceneSwitch()) return;
            EnsureFolders(Root, "Materials", "Textures", "Prefabs", "Scenes");
            string T = Root + "/Textures/", M = Root + "/Materials/M_" + Effect + "_";

            // 1. Textures (Shape Lab: Slash, CoreFire (DirectionalFlame03), FireTongue, Smoke; rest from make_texture.py)
            var tSlash = ImportTexture(T + "T_Explosion_Slash_4x2.png", 1024);
            var tSmoke = ImportTexture(T + "T_Explosion_Smoke_4x2.png", 1024);
            var tGlow = ImportTexture(T + "T_Glow_Soft.png", 512);
            var tSpark = ImportTexture(T + "T_Spark_Comet.png", 256);
            var tDot = ImportTexture(T + "T_Dot_Scorch.png", 256, alphaFromGray: true);

            // 2. Materials
            var mFlash = Material(M + "Flash_Add.mat", VfxBlend.Additive, tGlow);
            var mSlash = Material(M + "Slash_Add.mat", VfxBlend.Additive, tSlash);
            var mSmoke = Material(M + "Smoke_Alpha.mat", VfxBlend.Alpha, tSmoke);
            var mSpark = Material(M + "Sparks_Add.mat", VfxBlend.Additive, tSpark);
            var mScorch = Material(M + "Scorch_Alpha.mat", VfxBlend.Alpha, tDot);

            var hot = new Color(1f, 0.82f, 0.42f);
            var orange = new Color(1f, 0.55f, 0.12f);
            var red = new Color(0.55f, 0.1f, 0.04f);

            var root = new GameObject("VFX_" + Effect);
            var rt = root.transform;

            // Ground Scorch: dark mark on the floor, fades slowly
            var scorch = Particle(rt, "Decal_Scorch", mScorch, 2.2f, 5.5f, new Color(0.04f, 0.03f, 0.02f, 0.75f));
            Horizontal(scorch, 0.02f, -2);
            SizeOverLifetime(scorch, 0f, 0.5f, 0.15f, 0.95f, 1f, 1f);
            AlphaOverLifetime(scorch, 0f, 0f, 0.05f, 1f, 0.6f, 0.8f, 1f, 0f);

            // Smoke: dark lobed puffs rising and tearing from the core outwards
            var smoke = Particle(rt, "Smoke", mSmoke, 1.8f, 3.5f, new Color(0.16f, 0.14f, 0.13f, 1f));
            Burst(smoke, 12);
            Sphere(smoke, 1.1f);
            var sm = smoke.main;
            sm.startDelay = 0.15f;
            sm.startLifetime = new ParticleSystem.MinMaxCurve(1.5f, 2.1f);
            sm.startSize = new ParticleSystem.MinMaxCurve(3.4f, 5f);
            sm.startSpeed = new ParticleSystem.MinMaxCurve(0.6f, 1.8f);
            sm.startRotation = new ParticleSystem.MinMaxCurve(0f, TwoPi);
            Rise(smoke, 1.2f);
            SizeOverLifetime(smoke, 0f, 0.55f, 1f, 1.3f);
            Sheet(smoke, 4, 2, 7);
            Sort(smoke, 0);

                                                // Impact: Slash spikes (Shape Lab), radial burst
            var slash = Particle(rt, "Impact", mSlash, 0.4f, 4f, new Color(1f, 0.7f, 0.28f, 0.9f));
            Burst(slash, 8);
            var sl = slash.main;
            sl.startSize = new ParticleSystem.MinMaxCurve(3.5f, 6f);
            sl.startRotation = new ParticleSystem.MinMaxCurve(0f, TwoPi);
            SizeOverLifetime(slash, 0f, 0.5f, 0.3f, 1f, 1f, 1.1f);
            Sheet(slash, 4, 2, 7);
            Sort(slash, 4);

            var flash = Particle(rt, "Glow", mFlash, 0.16f, 4.5f, new Color(1f, 0.93f, 0.7f));
            SizeOverLifetime(flash, 0f, 0.35f, 0.4f, 1f, 1f, 1.2f);
            AlphaOverLifetime(flash, 0f, 1f, 0.3f, 0.9f, 1f, 0f);
            Sort(flash, 5);

            // Sparks
            var sparks = Particle(rt, "Sparks", mSpark, 0.8f, 0.3f, new Color(1f, 0.75f, 0.3f));
            Burst(sparks, 30);
            Sphere(sparks, 0.2f);
            var pm = sparks.main;
            pm.startLifetime = new ParticleSystem.MinMaxCurve(0.5f, 1f);
            pm.startSpeed = new ParticleSystem.MinMaxCurve(8f, 16f);
            pm.startSize = new ParticleSystem.MinMaxCurve(0.25f, 0.45f);
            pm.gravityModifier = 1.2f;
            var pr = sparks.GetComponent<ParticleSystemRenderer>();
            pr.renderMode = ParticleSystemRenderMode.Stretch;
            pr.lengthScale = 1.5f; pr.velocityScale = 0.06f;
            ColorOverLifetime(sparks, new[] { hot, orange }, 0f, 1f, 0.6f, 0.9f, 1f, 0f);
            SizeOverLifetime(sparks, 0f, 1f, 1f, 0.3f);
            Sort(sparks, 6);

                        // 4. Save, validate, preview, demo scene
            var prefab = SavePrefab(root, Root + "/Prefabs/VFX_" + Effect + ".prefab");
            Finish(prefab, Root, Effect, new[] { 0.04f, 0.12f, 0.25f, 0.45f, 0.8f, 1.3f, 2f },
                new Vector3(0f, 4.5f, -9f), new Vector3(0f, 1.3f, 0f));
        }

        static void Sphere(ParticleSystem ps, float radius)
        {
            var s = ps.shape;
            s.enabled = true;
            s.shapeType = ParticleSystemShapeType.Sphere;
            s.radius = radius;
            s.radiusThickness = 1f;
        }

        static void Horizontal(ParticleSystem ps, float y, int order)
        {
            ps.transform.localPosition = new Vector3(0f, y, 0f);
            ps.GetComponent<ParticleSystemRenderer>().renderMode = ParticleSystemRenderMode.HorizontalBillboard;
            Sort(ps, order);
        }

        static void Rise(ParticleSystem ps, float speed)
        {
            var v = ps.velocityOverLifetime;
            v.enabled = true;
            v.space = ParticleSystemSimulationSpace.World;
            v.x = new ParticleSystem.MinMaxCurve(0f);
            v.y = new ParticleSystem.MinMaxCurve(speed);
            v.z = new ParticleSystem.MinMaxCurve(0f);
        }

        static void Sheet(ParticleSystem ps, int cols, int rows, int usedFrames)
        {
            var t = ps.textureSheetAnimation;
            t.enabled = true;
            t.mode = ParticleSystemAnimationMode.Grid;
            t.numTilesX = cols;
            t.numTilesY = rows;
            t.animation = ParticleSystemAnimationType.WholeSheet;
            t.frameOverTime = Curve(0f, 0f, 1f, (usedFrames - 0.01f) / (cols * rows));
            t.cycleCount = 1;
        }

        static void Sort(ParticleSystem ps, int order) =>
            ps.GetComponent<ParticleSystemRenderer>().sortingOrder = order;

        public static void BuildBatch() => RunBatch(Build);
    }
}
#endif
